def fill(g):
    H,W=len(g),len(g[0])
    cs=find(g); filled={}; colors={}
    for idx,c in enumerate(cs):
        touches=any(i in(0,H-1) or j in(0,W-1) for i,j in c)
        col=7 if len(c)==1 and not touches else (8 if not touches else 0)
        if col:
